// Uretildi: ~/inventory/harness/clibuild.js — elle duzenlemeyin
(window.CG_CLI_DATA = window.CG_CLI_DATA || {})["fortigate"] = {"key":"fortigate","name":"FortiGate (FortiOS)","commands":[{"cat":"System","code":"get system status","desc":"Firmware versiyonu, seri no, hostname, uptime, HA modu (master/slave/standalone), operation mode (NAT/Transparent). HA'da hangi cihazda oldugunuzu seri no'dan anlarsiniz","sev":"i"},{"cat":"System","code":"get system performance status","desc":"CPU kullanimi (user/system/idle per core), memory kullanimi (%), network throughput (kbps), session sayisi. idle<%30 = KRITIK, memory>%88 = conserve mode riski","sev":"i"},{"cat":"System","code":"execute time","desc":"Sistem saatini gosterir. NTP senkron degilse loglar yanlis zaman damgali olur. Sertifika dogrulama hatalarina da yol acabilir","sev":"i"},{"cat":"System","code":"diagnose sys top","desc":"Process listesi — CPU% ve MEM% ile. 'R'=Running, 'S'=Sleep, 'Z'=Zombie, 'D'=Disk Sleep. 'm' tusuna basinca memory'ye gore siralar. ipsengine yuksekse IPS agir, wad yuksekse proxy agir","sev":"w"},{"cat":"System","code":"diagnose sys top-summary","desc":"Process ozet tablosu — her process'in toplam CPU ve memory kullanimi. diagnose sys top'tan daha ozet ve okunakli","sev":"i"},{"cat":"System","code":"get system performance firewall packet-distribution","desc":"Paket boyutu dagilimi (64byte, 128, 256, 512, 1024, 1518+). Kucuk paketler coksa (64byte) CPU yuklenir. VoIP/gaming ortaminda normal olabilir","sev":"i"},{"cat":"System","code":"get system info admin status","desc":"Su anda login olan admin kullanicilari ve oturum bilgileri. Yetkisiz erisim kontrolu icin kullanilir","sev":"i"},{"cat":"System","code":"get system global | grep two","desc":"Two-factor authentication ayarini kontrol eder. two-factor-* satirlari two-factor auth durumunu gosterir","sev":"i"},{"cat":"System","code":"show full-configuration system global | grep port","desc":"Admin GUI portu (default 443), SSH portu (default 22) gibi global port ayarlarini gosterir","sev":"i"},{"cat":"System","code":"diagnose hardware sysinfo memory","desc":"Detayli bellek bilgisi: MemTotal, MemFree, Buffers, Cached, SwapTotal/Free. 'MemFree + Buffers + Cached' = kullanilabilir bellek","sev":"i"},{"cat":"System","code":"diagnose hardware sysinfo cpu","desc":"CPU modeli, core sayisi, clock hizi. Cihaz kapasitesini dogrulamak icin","sev":"i"},{"cat":"System","code":"diagnose hardware deviceinfo disk","desc":"Disk bilgisi: tip, boyut, bos alan. Log diski doluysa loglar yazilmaz. 'execute formatlogdisk' ile formatlanabilir","sev":"i"},{"cat":"System","code":"diagnose sys flash list","desc":"Flash partition listesi — hangi firmware aktif, boyut, bos alan. Dual firmware destegi varsa yedek image burada gorulur","sev":"i"},{"cat":"System","code":"diagnose hardware sysinfo interrupts","desc":"Hardware interrupt sayaclari. Anormal yuksek interrupt CPU sorununa isaret edebilir. NIC driver veya hardware sorunu teshisi icin","sev":"i"},{"cat":"System","code":"diagnose hardware test suite all","desc":"HQIP hardware diagnostic — CPU, memory, disk, NIC, PSU, fan testi. Sonuc PASS/FAIL olarak doner. RMA oncesi calistirilir","sev":"w"},{"cat":"System","code":"diagnose sys mpstat {n}","desc":"Her {n} saniyede bir core bazli CPU kullanimi. Tek core'da bottleneck varsa gorunur. Parametre: {n}=yenileme suresi (saniye)","sev":"i"},{"cat":"System","code":"diagnose firewall packet distribution","desc":"Firewall engine uzerinden gecen paketlerin boyut dagilimi istatistikleri","sev":"i"},{"cat":"System","code":"diagnose sys vd list","desc":"VDOM (Virtual Domain) listesi ve her VDOM'un istatistikleri — session sayisi, trafik. Multi-VDOM ortaminda onemli","sev":"i"},{"cat":"System","code":"diagnose sys cmdb info","desc":"Son konfigurasyon degisiklikleri — ne zaman, hangi admin. Config degisiklik takibi icin. Beklenmeyen degisiklikleri tespit eder","sev":"i"},{"cat":"System","code":"diagnose debug config-error-log read","desc":"Konfigurasyon dosyasindaki syntax hatalari. Firmware upgrade sonrasi uyumsuz config satirlarini gosterir. Bos cikti = sorun yok","sev":"e"},{"cat":"System","code":"diagnose debug crashlog read","desc":"Daemon crash loglari — hangi process ne zaman crash olmus. Tekrar eden crash'ler firmware bug isareti olabilir. TAC'a gonderin","sev":"e"},{"cat":"System","code":"execute tac report","desc":"Fortinet TAC (Technical Assistance Center) icin detayli sistem raporu olusturur. Destek bileti acilirken istenir","sev":"i"},{"cat":"System","code":"execute reboot","desc":"Cihazi yeniden baslatir. Onay ister: 'Do you want to continue? (y/n)'. Aktif trafik KESILIR","sev":"e"},{"cat":"System","code":"execute factoryreset","desc":"Tum konfigurasyonu siler, fabrika ayarlarina doner ve reboot eder. GERI ALINAMAZ! VM'de [keepvmlicense] parametresi lisansi korur","sev":"e"},{"cat":"System","code":"execute factoryreset2","desc":"factoryreset gibi ama system settings (interface IP, routing, admin password) KORUNUR. Firewall policy vs. silinir","sev":"e"},{"cat":"System","code":"show","desc":"Sadece default'tan farkli (degistirilmis) konfigurasyonu gosterir. Daha kisa ve okunakli. Konfig yedegi icin idealdir","sev":"i"},{"cat":"System","code":"show full-configuration","desc":"TUM konfigurasyonu gosterir (default degerler dahil). Cok uzun cikti. Karsilastirma veya tam yedek icin","sev":"i"},{"cat":"System","code":"tree","desc":"Tum CLI komut agacini gosterir — mevcut tum komutlari kesfetmek icin. Cok uzun cikti verir","sev":"i"},{"cat":"System","code":"tree execute","desc":"Sadece 'execute' altindaki komut agaci. Ping, traceroute, reboot gibi calistirma komutlarini listeler","sev":"i"},{"cat":"System","code":"tree diagnose","desc":"Sadece 'diagnose' altindaki komut agaci. Debug, sniffer, vpn, sys gibi teshis komutlarini listeler","sev":"i"},{"cat":"Hardware","code":"get hardware status","desc":"Model adi, seri no, BIOS versiyonu, RAM boyutu, disk tipi/boyutu. Cihaz envanter bilgisi icin kullanilir","sev":"i"},{"cat":"Hardware","code":"get hardware nic port3","desc":"NIC detayi: MAC adresi, driver, state (up/down), speed, duplex, Rx/Tx paket sayilari, drop/error sayaclari. Hata sayaclari 0'dan buyukse fiziksel sorun var","sev":"i"},{"cat":"Hardware","code":"diagnose hardware deviceinfo nic port3","desc":"get hardware nic ile ayni ciktiyi verir. CRC_errors>0 ise kablo/port kotu. Collisions>0 ise duplex mismatch","sev":"i"},{"cat":"Hardware","code":"get system interface physical","desc":"Tum fiziksel interface'lerin ozeti: status (up/down), IP adresi, speed (1000full/100half/n/a), Rx/Tx byte. Hizli genel bakis icin","sev":"i"},{"cat":"Hardware","code":"diagnose sys modem detect","desc":"USB/dahili modem tespiti. 3G/4G modem takiliysa burada gorulur. FEXT olmayan cihazlarda dahili modem kontrolu icin","sev":"i"},{"cat":"Hardware","code":"execute disk list","desc":"Mount edilmis diskleri listeler: tip (SSD/HDD/Flash), boyut, partition bilgisi. Log diski kontrol etmek icin","sev":"i"},{"cat":"Hardware","code":"execute formatlogdisk","desc":"Log diskini formatlar — TUM LOGLAR SILINIR! Disk doluysa veya bozuksa kullanilir. Onay ister, GERI ALINAMAZ","sev":"e"},{"cat":"Hardware","code":"fnsysctl ifconfig -a wan","desc":"Linux ifconfig ciktisi — interface MTU, flags, Rx/Tx istatistikleri. MTU degerini gormek icin TEK yol budur. fnsysctl = FortiOS shell komutu","sev":"i"},{"cat":"Interface","code":"show system interface","desc":"Tum interface konfigurasyonu — default'tan farkli ayarlar. IP, mode (static/dhcp/pppoe), allowaccess, vdom, status gorunur","sev":"i"},{"cat":"Interface","code":"show system interface FEXT","desc":"Belirli interface'in konfigurasyonunu goster. Interface adi buyuk/kucuk harf duyarlidir","sev":"i"},{"cat":"Interface","code":"get system interface","desc":"Tum interface'lerin ozet listesi: ad, IP, status, MTU, vdom. Hizli genel bakis icin","sev":"i"},{"cat":"Interface","code":"get system interface physical","desc":"Fiziksel interface'ler: status=up/down, IP, speed (1000full/100half/n/a), Rx/Tx byte. down=kablo yok veya admin down, speed=n/a ise link yok","sev":"i"},{"cat":"Interface","code":"diagnose ip address list","desc":"Tum interface'lerdeki IP/subnet bilgisi listesi. Secondary IP'ler dahil gorunur. IP catisma kontrolu icin kullanilir","sev":"i"},{"cat":"Interface","code":"get sys interface transceiver","desc":"SFP/SFP+ transceiver bilgisi: vendor, seri no, sicaklik, voltaj, TX/RX sinyal gucu (dBm). Fiber baglantilarda sinyal kalitesi kontrolu icin","sev":"i"},{"cat":"Interface","code":"show system interface port1 | grep -A2 ip","desc":"port1 konfigurasyonunda 'ip' iceren satir ve sonraki 2 satiri filtreler. Hizlica IP adresini bulmak icin","sev":"i"},{"cat":"Interface","code":"config system interface","desc":"Interface konfigurasyonu moduna girer. Ardindan 'edit <interface_adi>' ile belirli interface secilir. 'end' ile cikilir","sev":"i"},{"cat":"Interface","code":"edit wan1","desc":"Config modunda belirli interface'i sec. Ardindan set/show/get komutlari bu interface icin calisir","sev":"i"},{"cat":"Interface","code":"show full-configuration","desc":"Config modu icinde: tum ayarlari goster (default dahil). 'show' ise sadece degistirilmisleri gosterir","sev":"i"},{"cat":"Interface","code":"set status down","desc":"Interface'i administratif olarak kapatir. Trafik KESILIR! HA failover testi veya sorun izolasyonu icin kullanilir","sev":"e"},{"cat":"Interface","code":"set status up","desc":"Interface'i tekrar acar. Fiziksel link varsa trafik akmaya baslar. HA testinden sonra mutlaka UP yapin","sev":"ok"},{"cat":"Interface","code":"show system interface internal1","desc":"FEXT (FortiExtender) bagli internal switch portunun konfigurasyonu. DHCP server, allowaccess ayarlari burada","sev":"i"},{"cat":"Session","code":"get system session status","desc":"Toplam aktif session sayisi. Model limitine yaklasiyorsa conserve mode riski. Limit asildiysa yeni baglanti kabul edilmez","sev":"i"},{"cat":"Session","code":"get system session-info full-stat","desc":"Detayli istatistikler: mevcut sayi, global limit, TCP per-state breakdown, clash sayilari. memory_tension_drop>0 ise memory yetersiz","sev":"i"},{"cat":"Session","code":"get system session list","desc":"Tum session'lari basit formatta listeler. Cikti cok buyuk olabilir! Belirli IP icin 'grep' ile filtreleyin","sev":"i"},{"cat":"Session","code":"get system session list | grep 10.64.9.84","desc":"Belirli IP'nin session'larini filtreler. Hizli kontrol icin ama detay icin diagnose sys session kullanin","sev":"i"},{"cat":"Session","code":"get system session-ttl","desc":"Default TCP idle timeout suresi (varsayilan 3600sn=1saat). Bu sure dolunca inaktif session silinir. Kisa tutmak session sayisini dusurur","sev":"i"},{"cat":"Session","code":"get system global | grep -i timer","desc":"Global TCP/UDP session timeout degerleri. tcp-halfclose-timer, tcp-halfopen-timer, tcp-timewait-timer gibi ince ayarlar","sev":"i"},{"cat":"Session","code":"diagnose sys session stat","desc":"Session engine istatistikleri: clash, memory_tension_drop, TCP state dagilimlari. memory_tension_drop>0 = conserve mode belirtisi","sev":"i"},{"cat":"Session","code":"diagnose sys session exp-stat","desc":"Expectation (beklenen) session istatistikleri. FTP, SIP gibi multi-port protokollerde data channel icin olusturulan bekleme kayitlari","sev":"i"},{"cat":"Session","code":"diagnose sys session filter","desc":"Aktif filtreleri goster. Liste/clear oncesi mevcut filtreleri kontrol edin. Filtre yoksa list/clear TUM session'lari etkiler!","sev":"i"},{"cat":"Session","code":"diagnose sys session filter <filter>","desc":"Filtre parametreleri: src, dst, sport, dport, proto (6=TCP,17=UDP), policy, vd, sintf, dintf, duration, expire, negate. Birden fazla filtre AND mantigi ile calisir","sev":"i"},{"cat":"Session","code":"diagnose sys session list","desc":"Filtrelenmis session detayi: proto, proto_state (TCP:00=yeni/01=established/02=closing), policy_id, state flags (may_dirty/dirty/npu/local), duration/expire/timeout, NAT bilgisi, byte sayaclari","sev":"i"},{"cat":"Session","code":"diagnose sys session clear","desc":"Filtreye uyan session'lari SILER. DIKKAT: Filtre yoksa TUM session'lar silinir! Once 'diagnose sys session filter' ile filtreyi dogrulayin","sev":"e"},{"cat":"Routing","code":"get router info routing-table all","desc":"Tam routing tablosu (RIB). Kodlar: S=Static, C=Connected, O=OSPF, B=BGP, *=default route. [distance/metric] dusuk distance=oncelikli (S=10, O=110, B=200)","sev":"i"},{"cat":"Routing","code":"get router info routing-table database","desc":"Tum bilinen route'lar — aktif olmayanlar dahil. RIB'e girmeyen (daha yuksek distance) route'lar da gorulur. Neden secilmedigini anlamak icin","sev":"i"},{"cat":"Routing","code":"get router info routing-table static","desc":"Sadece statik route'lari gosterir. 'via' next-hop IP ve cikis interface'ini belirtir","sev":"i"},{"cat":"Routing","code":"show router static","desc":"Konfigure edilmis statik route'larin konfigurasyonu. dst/gateway/device/distance/priority alanlari gorunur. 'get' ciktisini gostermez, konfig'u gosterir","sev":"i"},{"cat":"Routing","code":"get router info kernel","desc":"Kernel FIB (Forwarding Information Base) — gercekte kullanilan routing tablosu. tab, vf (VDOM), type, proto, prio, pref, Gwy (gateway), dev (device) alanlari var","sev":"i"},{"cat":"Routing","code":"diagnose ip route list","desc":"Kernel seviyesinde IP route listesi. get router info kernel ile benzer ama farkli format. Routing daemon'undan bagimsiz","sev":"i"},{"cat":"Routing","code":"diagnose ip rtcache list","desc":"Route cache — son kullanilan route'lar onbellekte tutulur. Eski/yanlis cache routing sorununa yol acabilir","sev":"i"},{"cat":"Routing","code":"diagnose firewall proute list","desc":"Policy route (PBR/SD-WAN) listesi. Normal routing'den ONCE uygulanir! src/dst/out/gateway/used alanlari. used=0 ise hic eslesme olmamis","sev":"i"},{"cat":"Routing","code":"diagnose firewall proute list <id>","desc":"ID ile belirli policy route detayi. Uzun ID numarasi 'diagnose firewall proute list' ciktisindaki id alanından alinir","sev":"i"},{"cat":"Routing","code":"get router info protocols","desc":"Aktif routing protokollerini gosterir: static, connected, OSPF, BGP, RIP. Hangi protokollerin calistigini dogrulamak icin","sev":"i"},{"cat":"Routing","code":"execute router restart","desc":"Routing daemon'unu (zebos) yeniden baslatir. OSPF/BGP komsulari KOPAR ve yeniden kurulur. Son care olarak kullanin, trafik etkilenir","sev":"e"},{"cat":"Routing","code":"show router policy 1","desc":"PBR (Policy Based Routing) kural konfigurasyonunu gosterir: src/dst adresleri, cikis interface, gateway, protocol","sev":"i"},{"cat":"OSPF","code":"get router info ospf status","desc":"OSPF process durumu: Router ID, area listesi, SPF hesaplama sayisi, son SPF zamani. OSPF calisiyor mu kontrolu icin ilk komut","sev":"i"},{"cat":"OSPF","code":"get router info ospf neighbor","desc":"OSPF komsulari: Neighbor ID, Priority, State, Dead Time, Address, Interface. State: Full=OK, Init/2Way=sorun var, Down=komsu kayip","sev":"i"},{"cat":"OSPF","code":"get router info ospf neighbor all","desc":"TUM OSPF komsulari (farkli area'lar dahil). Full/DR veya Full/BDR=normal. Init=hello aliniyor ama ilerlemiyor (timer/area/auth sorunu)","sev":"i"},{"cat":"OSPF","code":"get router info ospf interface","desc":"OSPF interface'leri: network type, area, cost, hello/dead interval, DR/BDR election durumu. Timer mismatch komsu sorununa yol acar","sev":"i"},{"cat":"OSPF","code":"get router info ospf database brief","desc":"OSPF LSDB (Link State Database) ozeti: Router/Network/Summary/External LSA sayilari. Database buyuklugu OSPF performansini etkiler","sev":"i"},{"cat":"OSPF","code":"diagnose ip router ospf all enable","desc":"OSPF debug baslat — hello paketleri, LSA exchange, SPF hesaplamasi. Yogun cikti uretir! 'diagnose debug enable' ile birlikte kullanin","sev":"w"},{"cat":"OSPF","code":"diagnose ip router ospf level info","desc":"OSPF debug seviyesini info'ya ayarlar. Debug baslatmadan ONCE calistirin. error/warning/info/debug seviyeleri var","sev":"i"},{"cat":"BGP","code":"get router info bgp summary","desc":"BGP ozet tablosu: Neighbor IP, AS, MsgRcvd/Sent, Up/Down time, State/PfxRcd. State=Established=OK, Idle/Active/Connect=sorun. PfxRcd=alinan prefix sayisi","sev":"i"},{"cat":"BGP","code":"get router info bgp neighbors","desc":"BGP neighbor detaylari: remote AS, local AS, hold time, keepalive, capabilities (route-refresh, 4-byte AS, graceful-restart)","sev":"i"},{"cat":"BGP","code":"get router info bgp neighbors <x.x.x.x> advertised-routes","desc":"Bu peer'a gondigimiz route'lar. Bos ise route-map/prefix-list filtreliyor olabilir veya redistribute yapilandirilmamis","sev":"i"},{"cat":"BGP","code":"get router info bgp neighbors <x.x.x.x> received-routes","desc":"Bu peer'dan ALINAN tum route'lar (filtre oncesi). Peer'in gonderdigini dogrulamak icin. soft-reconfiguration inbound gerekli","sev":"i"},{"cat":"BGP","code":"get router info bgp neighbors <x.x.x.x> routes","desc":"Bu peer'dan alinan ve RIB'e KURULAN route'lar. received-routes ile farki: route-map filtresi uygulanmis hali","sev":"i"},{"cat":"BGP","code":"diagnose ip router bgp all enable","desc":"BGP debug baslat — update, notification, keepalive mesajlari. 'diagnose debug enable' ile birlikte. Yogun peer ortaminda filtresiz calistirilmamali","sev":"w"},{"cat":"BGP","code":"diagnose ip router bgp level info","desc":"BGP debug seviyesini info'ya ayarlar. Debug oncesi calistirin","sev":"i"},{"cat":"BGP","code":"execute router clear bgp all","desc":"TUM BGP peer'lari HARD reset — TCP session kopar, tum route'lar silinir, yeniden negotiate. TRAFIK KESILIR! Son care","sev":"e"},{"cat":"BGP","code":"execute router clear bgp all soft in","desc":"Inbound policy degisikligini uygulamak icin soft reset. Peer baglantisi KOPMAZ, sadece route'lar yeniden islenir. Guvenli","sev":"w"},{"cat":"BGP","code":"execute router clear bgp all soft out","desc":"Outbound policy degisikligini uygulamak icin soft reset. Peer'lara yeniden update gonderilir. Baglanti kopmaz","sev":"w"},{"cat":"BGP","code":"execute router clear bgp ip x.x.x.x soft in","desc":"Belirli peer icin inbound soft reset. Sadece bu peer'dan alinan route'lar yeniden islenir. En guvenli yontem","sev":"w"},{"cat":"ARP","code":"get system arp","desc":"ARP tablosu: Address (IP), Age (dk), Hardware Addr (MAC), Interface. Age=0 ise taze kayit. Ayni IP farkli MAC = IP catismasi!","sev":"i"},{"cat":"ARP","code":"get system arp | grep 192.168.1.2","desc":"Belirli IP'nin ARP kaydini filtreler. MAC gorunuyorsa L2 baglanti var. 00:00:00:00:00:00 ise cozumlenemedi (hedef yanit vermiyor)","sev":"i"},{"cat":"ARP","code":"diagnose ip arp list","desc":"Detayli ARP bilgisi: port, IP, MAC, state, flag. 'get system arp' ile benzer ama daha fazla teknik detay icerir","sev":"i"},{"cat":"ARP","code":"diagnose ip arp list | grep 192.168.1.57","desc":"Belirli IP icin detayli ARP. State alaninda incomplete=cozumlenemedi, reachable=OK, stale=eski kayit (yenilenmedi)","sev":"i"},{"cat":"ARP","code":"execute clear system arp table","desc":"TUM ARP tablosunu siler. Gecici L2 kesintisi olusabilir — cihazlar yeniden ARP yapana kadar. IP catismasi cozumu icin kullanilir","sev":"e"},{"cat":"Ping","code":"execute ping-options view-settings","desc":"Mevcut ping ayarlarini gosterir: repeat-count, data-size, timeout, source, ttl, df-bit, interface. Ayar degistirildiyse kalici olur!","sev":"i"},{"cat":"Ping","code":"execute ping-options repeat-count 19","desc":"Ping tekrar sayisini 19 yapar (default 5). Uzun sureli baglanti testi icin artirin. Paket kaybi oranini daha iyi gosterir","sev":"i"},{"cat":"Ping","code":"execute ping-options source 192.168.1.1","desc":"Ping kaynak IP'sini ayarlar. KRITIK: VPN uzerinden ping icin kaynak IP'nin VPN selector'undeki subnet'te olmasi gerekir. Yanlis source = yanit gelmez","sev":"i"},{"cat":"Ping","code":"execute ping 192.168.1.28","desc":"ICMP echo request gonderir. 0% loss=OK, 100% loss=hedef ulasilamaz (firewall/routing/hedef down). TTL: 64=Linux, 128=Windows, 255=network cihazi","sev":"i"},{"cat":"Ping","code":"execute ping -c 3 10.64.0.29","desc":"FEXT'te 3 paketlik ping. -c parametresi sadece bazi cihazlarda calisir. FortiGate'de repeat-count kullanin","sev":"i"},{"cat":"Ping","code":"execute traceroute <x.x.x.x>","desc":"Hedefe giden yolu gosterir: her hop'un IP'si ve response suresi. * * * = ICMP engellenmis veya timeout. Routing sorunlarini tespitte cok onemli","sev":"i"},{"cat":"Ping","code":"execute traceroute-options {options}","desc":"Traceroute ayarlari: source (kaynak IP), device (cikis interface), use-sdwan yes (SD-WAN uzerinden). view-settings ile mevcut ayarlari gorun","sev":"i"},{"cat":"Connectivity","code":"execute telnet 1.1.1.2","desc":"Telnet ile uzak cihaza baglanir. Port erisimi testi icin: port aciksa 'Connected' gorulur. Timeout = port kapali veya firewall engeller","sev":"i"},{"cat":"Connectivity","code":"execute telnet 192.0.2.5","desc":"FEXT'e veya uzak cihaza telnet. CPE yonetimi icin kullanilir. Telnet guvenli degildir — sadece LAN/yonetim amaciyla","sev":"i"},{"cat":"Connectivity","code":"execute ssh admin@1.1.1.2","desc":"SSH ile uzak cihaza baglanir. admin=kullanici adi. FortiGate'den baska FortiGate veya switch'e yonetim amacli erisim icin","sev":"i"},{"cat":"Connectivity","code":"execute ssh-options {options}","desc":"SSH ayarlari: source (kaynak IP), port (hedef port, default 22). Farkli porttan SSH baglantisi icin 'port 2222' gibi","sev":"i"},{"cat":"Sniffer","code":"diagnose sniffer packet any 'host 10.64.30.2' 4 0","desc":"Belirli IP'nin tum trafigini yakala. verbose=4 interface adi gosterir (en cok kullanilan). count=0 sinirsiz (Ctrl+C ile dur). Trafik var mi yok mu ilk kontrol","sev":"i"},{"cat":"Sniffer","code":"diagnose sniffer packet any 'host 10.64.30.2 and port 443' 4 0","desc":"IP + port filtreli — sadece HTTPS trafigini yakalar. 'and' operatoru iki kosulu birlestirir. BPF (Berkeley Packet Filter) syntax kullanilir","sev":"i"},{"cat":"Sniffer","code":"diagnose sniffer packet any 'host 192.0.2.42 and port 500' 4 0 1","desc":"IKE (port 500) trafik yakalama — IPsec VPN troubleshoot icin. Son parametre 1=UTC timestamp. Karsi taraftan IKE paketi geliyor mu kontrolu","sev":"i"},{"cat":"Sniffer","code":"diagnose sniffer packet any 'src host 192.0.2.152 and dst host 10.128.4.6' 4 a","desc":"Tek yonlu filtre — sadece bu kaynak'tan bu hedef'e. 'a'=absolute timestamp (tarih+saat). Asimetrik routing tespiti icin ideal","sev":"i"},{"cat":"Sniffer","code":"diagnose sniffer packet any 'host 172.24.1.1' 6","desc":"Verbose 6 = en detayli: Ethernet header + IP header + payload hex + ASCII dump. Paket icerigini okumak icin (sifrelenmemis trafik). CPU yogun!","sev":"i"},{"cat":"Sniffer","code":"diagnose sniffer packet <interface> <'filter'> <verbose> <count> <a|l>","desc":"Genel syntax. interface: any/wan1/port5. filter: BPF syntax (host/port/src/dst/and/or/not). verbose: 1-6. count: 0=sinirsiz. timestamp: a=UTC, l=local","sev":"i"},{"cat":"Debug Flow","code":"diagnose debug enable","desc":"Debug ciktisini konsola baslat. BU OLMADAN hicbir debug ciktisi gelmez. Tum debug islemleri 'enable' gerektirir. 'diagnose debug info' ile durum kontrol edilir","sev":"w"},{"cat":"Debug Flow","code":"diagnose debug flow filter addr 192.168.2.169","desc":"IP filtresi — kaynak VEYA hedef olarak bu IP'yi iceren paketler. Birden fazla filtre (addr+port) AND mantigi ile calisir. Filtre koymadan trace baslatMAyin","sev":"i"},{"cat":"Debug Flow","code":"diagnose debug flow filter port 23","desc":"Port filtresi — kaynak VEYA hedef port. addr ile birlikte kullanildiginda AND olur: sadece o IP VE o port eslesince cikti gelir","sev":"i"},{"cat":"Debug Flow","code":"diagnose debug flow filter dport 8099","desc":"Sadece destination port filtresi. 'port' her iki yonu filtrelerken, 'dport' sadece hedef portu filtreler. 'sport' da kaynak portu filtreler","sev":"i"},{"cat":"Debug Flow","code":"diagnose debug flow show function-name enable","desc":"Her satirdaki FortiOS fonksiyon adini gosterir (init_ip_session, vf_ip_route_input, fw_forward_handler vs). Sorunun hangi asamada oldugunu anlamak icin KRITIK","sev":"i"},{"cat":"Debug Flow","code":"diagnose debug flow show iprope enable","desc":"Internal firewall policy (iprope) kontrol detaylarini gosterir. Policy eslesme sürecini adim adim gormenizi saglar. Gizli policy sorunlari icin","sev":"i"},{"cat":"Debug Flow","code":"diagnose debug flow trace start 100","desc":"100 satir debug ciktisi al. Sayi buyukse cok cikti gelir, kucukse sorunu yakalayamayabilirsiniz. Genellikle 50-200 arasi yeterli. Ctrl+C ile erken durdurulabilir","sev":"i"},{"cat":"Debug Flow","code":"diagnose debug flow trace start6 <n>","desc":"IPv6 trafik icin debug flow baslat. IPv4 ile ayni cikti formatinda. IPv6 routing/policy sorunlari icin","sev":"i"},{"cat":"Debug Flow","code":"diagnose debug console timestamp enable","desc":"Debug satirlarina tarih+saat damgasi ekler. Zamanlama analizleri icin onemli. Loglari baskasina gonderirken timestamp olmazsa anlamsiz olur","sev":"i"},{"cat":"Debug Flow","code":"diagnose debug flow filter clear","desc":"Tum IPv4 filtrelerini temizler. Debug bittikten sonra MUTLAKA calistirin. Filtre kalirsa bir sonraki debug yanlis sonuc verebilir","sev":"ok"},{"cat":"Debug Flow","code":"diagnose debug flow filter6 clear","desc":"IPv6 debug flow filtrelerini temizler. IPv6 debug sonrasi kullanin","sev":"ok"},{"cat":"Debug Flow","code":"diagnose debug flow trace stop","desc":"Aktif trace'i durdurur. 'disable' ile birlikte kullanin. Once stop, sonra disable, sonra filter clear sirasi idealdir","sev":"ok"},{"cat":"Debug Flow","code":"diagnose debug disable","desc":"Debug ciktisini durdurur ama background'da calisan debug'lar devam edebilir. Tam temizlik icin 'diagnose debug reset' kullanin","sev":"ok"},{"cat":"Debug Flow","code":"diagnose debug reset","desc":"TUM aktif debug'lari durdurur — foreground ve background. En temiz kapatma yontemi. Debug sonrasi MUTLAKA calistirin","sev":"ok"},{"cat":"Debug Flow","code":"diagnose debug duration 0","desc":"Debug suresini sinirsiz yapar (default 30dk). 0=sinirsiz, reboot sifirlar. Uzun sureli izleme icin. Unutursaniz cihaz yuklenir!","sev":"w"},{"cat":"IPsec","code":"get vpn ipsec tunnel summary","desc":"Tum tunnel'larin ozeti: isim, up/down durumu, local/remote IP, selector sayisi. DOWN gorurseniz Phase1/2 kontrol edin. 0.0.0.0 = peer IP alinamadi (Phase1 basarisiz)","sev":"i"},{"cat":"IPsec","code":"get vpn ipsec tunnel details","desc":"Detayli tunnel bilgisi: Rx/Tx paket/byte, peer IP, algorithm, selector, lifetime, NAT-T durumu. Trafik 0 ise tunnel calismiyordur","sev":"i"},{"cat":"IPsec","code":"get vpn ipsec tunnel name TUN_SUBE1","desc":"Belirli tunnel'in detayli bilgisi. Isim Phase1 config'deki isimdir. Tab ile otomatik tamamlanir","sev":"i"},{"cat":"IPsec","code":"diagnose vpn tunnel list name TUN_SUBE1","desc":"Phase 2 (IPsec SA) bilgisi: selector (src/dst subnet), SPI, enc/auth algorithm, NPU offload, MTU, lifetime, DPD durumu. Packets=0 ise trafik akmiyordur","sev":"i"},{"cat":"IPsec","code":"diagnose vpn ike gateway list name TUN_SUBE1","desc":"Phase 1 (IKE SA) bilgisi: status (established/connecting), created suresi, direction (initiator/responder), proposal (enc-hash). established 0/1 = SORUN","sev":"i"},{"cat":"IPsec","code":"diagnose vpn ike gateway list","desc":"TUM Phase 1 durumu. status:established=OK. XAuth dial-up icin kullanici adi da gorunur. Toplu kontrol icin","sev":"i"},{"cat":"IPsec","code":"diagnose vpn tunnel list","desc":"TUM Phase 2 durumu. Her tunnel icin selector, SPI, algorithm, paket sayaclari. Toplu kontrol icin","sev":"i"},{"cat":"IPsec","code":"diagnose vpn ipsec status","desc":"IPsec sifreleme istatistikleri: ASIC vs software crypto sayaclari. Software crypto yuksekse NPU offload calismiyordur (performans sorunu)","sev":"i"},{"cat":"IPsec","code":"diagnose vpn ike counts","desc":"IKE SA sayaclari: aktif tunnel sayisi, basarili/basarisiz negotiation sayilari. Basarisiz sayi artiyorsa surekli deneme var","sev":"i"},{"cat":"IPsec","code":"diagnose vpn ike errors","desc":"IKE hata sayaclari: no-proposal, auth-fail, timeout vs. Hangi hata tipinin en cok oldugunu gosterir. Sorunun kok nedenini bulmak icin","sev":"e"},{"cat":"IPsec","code":"diagnose vpn ike stats","desc":"IKE performans istatistikleri: negotiation sureleri, paket sayilari","sev":"i"},{"cat":"IPsec","code":"diagnose vpn ike routes","desc":"IKE tarafindan olusturulan route'lar. Tunnel UP olunca otomatik eklenen route'lar burada gorulur","sev":"i"},{"cat":"IPsec","code":"diagnose vpn ike status","desc":"IKE engine genel durum bilgisi","sev":"i"},{"cat":"IPsec","code":"diagnose vpn ike crypto","desc":"IKE crypto engine bilgisi: desteklenen algoritmalar, hardware acceleration durumu","sev":"i"},{"cat":"IPsec","code":"diagnose vpn tunnel flush","desc":"TUM Phase 2 SA'lari siler ve yeniden negotiate eder. Aktif tunnel trafigi KESILIR. Toplu VPN reset icin (dikkatli!)","sev":"e"},{"cat":"IPsec","code":"diagnose vpn tunnel flush <name>","desc":"Belirli tunnel'in Phase 2 SA'sini siler. Tunnel otomatik yeniden kurulur. Tek tunnel sorununda tercih edin","sev":"e"},{"cat":"IPsec","code":"diagnose vpn ike gateway clear name <name>","desc":"Phase 1 IKE SA'yi temizler. clear=graceful kapatma (notify gonderir). Karsi tarafa bildirim gider","sev":"e"},{"cat":"IPsec","code":"diagnose vpn ike gateway flush name <name>","desc":"Phase 1 IKE SA'yi flush eder. flush=zorla sil (notify gondermez). Karsi taraf timeout'a kadar eski SA'yi kullanmaya devam edebilir","sev":"e"},{"cat":"IPsec","code":"diagnose vpn ike restart","desc":"IKE daemon'unu yeniden baslatir. TUM VPN tunnel'lari KOPAR ve yeniden kurulur. Son care, cok sayida tunnel varsa dakikalarca surebilir","sev":"e"},{"cat":"IPsec","code":"diagnose vpn tunnel up <phase2> <phase1>","desc":"Belirli phase 2 SA'sini hemen kurmayi dener (trafik beklemeden). 7.4/7.6 CLI Ref: diagnose vpn tunnel up <phase2> <phase1> [serial]. Test icin; kalici cozum auto-negotiate","sev":"w"},{"cat":"IPsec","code":"diagnose vpn tunnel down <phase2> <phase1>","desc":"Belirli phase 2 SA'sini indirir; o tunelin trafigi KESILIR. Yeniden anahtarlama sorununu tetiklemek/test etmek icin","sev":"e"},{"cat":"IPsec Dial-up","code":"diagnose vpn ike gateway list","desc":"Dial-up istemcileri '<tunel>_0', '<tunel>_1' gibi ornek (instance) adlariyla gorunur: istemci genel IP'si, verilen IP, EAP kullanicisi (peer-id)","sev":"i"},{"cat":"IPsec Dial-up","code":"show full-configuration system settings | grep ike-tcp","desc":"IKE/IPsec icin TCP portu. Varsayilan 7.6'da 443, 7.4'te 4500 (CLI Ref system settings). 443 yonetim HTTPS portuyla ayni arayuzde cakisir: IKE onceliklidir, GUI erisimi kaybolur (7.6.3+ uyari verir)","sev":"i"},{"cat":"IPsec Dial-up","code":"set ike-tcp-port 443","desc":"config system settings altinda. FortiClient profilindeki TCP portuyla ayni olmali. Yonetim 443'te acik arayuzde kullanacaksaniz admin-sport'u degistirin","sev":"w"},{"cat":"IPsec Dial-up","code":"set transport auto","desc":"phase1-interface: once UDP 500/4500, engelliyse TCP (7.6 varsayilani). TCP tasima yalniz IKEv2 ve FortiClient 7.4.1+ ile calisir","sev":"i","ver":"7.6"},{"cat":"IPsec Dial-up","code":"set transport udp-fallback-tcp","desc":"phase1-interface: 7.4'teki karsiligi (7.4 degerleri: udp, udp-fallback-tcp, tcp; varsayilan udp). 7.6'da bu deger yok, 'auto' kullanilir","sev":"i","ver":"7.4"},{"cat":"IPsec Dial-up","code":"set transport tcp","desc":"phase1-interface: yalniz TCP (UDP'yi kesen otel/misafir aglari). Yalniz IKEv2; NPU hizlandirmasi kullanilmaz","sev":"i"},{"cat":"IPsec Dial-up","code":"set type dynamic","desc":"phase1-interface: dial-up sunucusu (karsi uc sabit IP degil). Birlikte: set mode-cfg enable, set ipv4-start-ip / ipv4-end-ip, set eap enable, set authusrgrp <grup>","sev":"i"},{"cat":"IPsec Debug","code":"diagnose vpn ike log filter rem-addr4 203.0.113.37","desc":"IKE debug'u belirli peer (karsi uc) IP'ye filtreler. Cok tunnel varsa filtresiz debug okunmaz olur. 7.4/7.6 parametreleri: rem-addr4, loc-addr4, name, dst-port, list, clear, negate. Not: eski surumlerde (7.2 dahil) bicim 'log-filter dst-addr4' idi; 7.4.8 ve 7.6'da bu bicim yok","sev":"i"},{"cat":"IPsec Debug","code":"diag vpn ike log filter name TUN_SUBE1","desc":"IKE debug'u tunnel ismine gore filtreler. Belirli bir tunnel'in negotiation surecini izlemek icin. 'list' ile aktif filtreleri, 'clear' ile temizleyin","sev":"i"},{"cat":"IPsec Debug","code":"diagnose vpn ike log filter list","desc":"Etkin IKE debug filtrelerini gosterir (7.4/7.6 sozdizimi: 'log filter', tiresiz)","sev":"i"},{"cat":"IPsec Debug","code":"diagnose vpn ike log filter clear","desc":"IKE debug filtrelerini temizler. Is bitince filtreyi temizlemek, sonraki debug'da 'cikti gelmiyor' saskinligini onler","sev":"ok"},{"cat":"IPsec Debug","code":"diagnose debug application ike 1","desc":"IKE debug seviye 1 — temel bilgi. Default 30dk sonra otomatik kapanir. Phase1/2 negotiation mesajlari: my proposal, incoming proposal, matched/no-match","sev":"w"},{"cat":"IPsec Debug","code":"diagnose debug application ike -1","desc":"IKE debug maximum verbosity (-1=tum seviyeler). Cok fazla cikti uretir! Filtre ile kullanin. Phase1/2 detaylari, crypto islemleri, paket hex dump dahil","sev":"w"},{"cat":"IPsec Debug","code":"diagnose debug enable","desc":"Debug ciktisini konsola baslat. IKE debug icin MUTLAKA gerekli. Once filter koyun, sonra 'application ike' acin, en son 'enable' yapin","sev":"w"},{"cat":"IPsec Debug","code":"diagnose debug disable","desc":"Debug ciktisini durdurur. Islem bittikten sonra MUTLAKA kapatin. Acik birakilan debug CPU tuketir ve konsolu kirletir","sev":"ok"},{"cat":"SSL VPN","code":"get vpn ssl monitor","desc":"Bagli SSL VPN kullanicilari: index, username, auth type, timeout countdown, source IP, HTTP/HTTPS in/out byte. Bos liste = kimse bagli degil","sev":"i"},{"cat":"SSL VPN","code":"get vpn ssl settings","desc":"SSL VPN konfigurasyonu: dinleme portu (default 443), interface, IP pool araligi, tunnel-ip-pools (7.6.3+ yok: Agentless VPN, tunel alanlari kaldirildi), dns-server. Port catismasi kontrolu icin onemli","sev":"i"},{"cat":"SSL VPN","code":"diagnose vpn ssl list","desc":"Aktif SSL VPN session listesi — tunnel mode ve web mode dahil. Her session'in detayli bilgisi: kullanici, IP, baglanti suresi, trafik","sev":"i"},{"cat":"SSL VPN","code":"execute vpn sslvpn list","desc":"SSL VPN baglanti listesi — get vpn ssl monitor'e benzer ama farkli format. Hizli kontrol icin","sev":"i"},{"cat":"SSL VPN","code":"diagnose vpn ssl statistics","desc":"SSL VPN motor istatistikleri: toplam baglanti, aktif session, max concurrent, hata sayaclari. Kapasite planlamasi icin","sev":"i"},{"cat":"SSL VPN","code":"diagnose vpn ssl mux-stat","desc":"(Yalniz FortiOS 7.4 ve oncesi; 7.6'da bu alt komut yok) SSL VPN multiplexing istatistikleri. Tunnel performansi analizi icin. Yuksek queue degeri bottleneck isareti","sev":"i","ver":"7.4"},{"cat":"SSL VPN","code":"execute vpn sslvpn del-tunnel","desc":"(7.6.3+ SSL-VPN tunel modu yok; komut listede kalsa da kesilecek tunel kullanicisi olmaz) TUM tunnel mode kullanicilarini keser. Belirli kullanici secimi YOKTUR — hepsi kesilir! Acil durumlarda veya IP pool sifirlama icin","sev":"e","ver":"7.4"},{"cat":"SSL VPN","code":"execute vpn sslvpn del-web","desc":"TUM web mode kullanicilarini keser. Web portal erisimlerini sonlandirir. Toplu oturum temizligi icin","sev":"e"},{"cat":"SSL VPN","code":"diagnose vpn ssl debug-filter <filter>","desc":"SSL VPN debug filtresi: src-addr4 (client IP), vd (VDOM). 'list' ile aktif filtreleri, 'clear' ile temizleyin. Filtresiz debug cok yogun!","sev":"i"},{"cat":"SSL VPN","code":"diagnose debug application sslvpn -1","desc":"SSL VPN debug — SSL protokol negotiation, cipher secimi, tunnel kurulumu. Kullanici adi/grup bilgisi GOSTERMEZ, bunun icin auth debug gerekir","sev":"w"},{"cat":"GRE","code":"show system gre-tunnel","desc":"GRE tunnel konfigurasyonu: isim, local/remote IP, interface. IPsec uzerine GRE kuruluyorsa burada gorunur. Routing protokolleri GRE uzerinden calisir","sev":"i"},{"cat":"GRE","code":"diagnose sys gre list","desc":"Aktif GRE tunnel'larin operasyonel durumu ve istatistikleri. Tunnel UP/DOWN durumu ve paket sayaclari","sev":"i"},{"cat":"Policy","code":"show firewall policy 1","desc":"Policy ID 1'in konfigurasyonu: srcintf/dstintf, srcaddr/dstaddr, action (accept/deny), service, NAT, UTM profilleri, schedule, logtraffic. Policy ID debug flow ciktisinda gorulur","sev":"i"},{"cat":"Policy","code":"show firewall policy","desc":"TUM firewall policy'leri — yukaridan asagiya sirayla. Ilk eslesen uygulanir! Cikti uzun olabilir, 'grep' ile filtreleyin","sev":"i"},{"cat":"Policy","code":"diagnose firewall iprope list","desc":"Internal compiled firewall tablosu — FortiGate'in gercekte kullandigi tablo. Policy siralama sorunlarini tespit etmek icin. Normal policy listesinden farkli olabilir","sev":"i"},{"cat":"Policy","code":"show router policy 1","desc":"PBR (Policy Based Routing) kural 1: src/dst adres, protocol, cikis interface, gateway. Normal routing'den ONCE uygulanir","sev":"i"},{"cat":"Policy","code":"diagnose firewall iprope lookup 10.64.10.50 50000 198.51.100.80 443 tcp port2 policy","desc":"Bu trafik hangi kurala duser? Kaynak IP/port, hedef IP/port, protokol, giris arayuzu ve kural tipi (policy | proxy; CLI Ref 7.4.8/7.6.6). Ciktida 'matches policy id: N'; 0 = ortuk deny. Trafik uretmeden kural sirasini test eder","sev":"i"},{"cat":"GeoIP","code":"diagnose geoip ip2country 198.51.100.80","desc":"IP adresinin ulke kodu (FortiGuard GeoIP veritabani). Geography tipli adres nesnesi (set type geography / set country TR) beklenmedik eslesiyorsa once burada dogrulayin","sev":"i"},{"cat":"GeoIP","code":"diagnose geoip geoip-query 198.51.100.80","desc":"GeoIP sorgusu: ulke ve ayrinti bilgisi. Yanlis ulke goruluyorsa FortiGuard GeoIP veritabani guncel mi kontrol edin","sev":"i"},{"cat":"GeoIP","code":"diagnose geoip iprange","desc":"Veritabanindaki IPv4 araliklari (cok uzun cikti; grep ile daraltin)","sev":"i"},{"cat":"Yedekleme","code":"execute backup config tftp <dosya> <tftp-sunucu>","desc":"Calisan yapilandirmayi TFTP sunucusuna yedekler. Degisiklikten ONCE alin; geri donus icin execute restore config tftp","sev":"ok"},{"cat":"Yedekleme","code":"execute backup config sftp <dosya> <sftp-sunucu>[:port] <kullanici> <parola>","desc":"SFTP ile sifreli yedek (TFTP ag uzerinde acik metin tasir). Uretimde tercih edilen yol","sev":"ok"},{"cat":"Yedekleme","code":"execute backup full-config tftp <dosya> <tftp-sunucu>","desc":"Varsayilanlar dahil TAM yapilandirma yedegi (show full-configuration karsiligi). Karsilastirma/denetim icin","sev":"i"},{"cat":"Yedekleme","code":"execute backup config flash <aciklama>","desc":"Yapilandirmayi cihazdaki revizyon deposuna kaydeder (aciklamali). Liste: execute revision list config","sev":"ok"},{"cat":"Yedekleme","code":"execute backup config usb <dosya>","desc":"USB bellege yedek (USB portu olan modellerde). 7.6.6 CLI Ref'te listelenir","sev":"i","ver":"7.6"},{"cat":"Yedekleme","code":"execute revision list config","desc":"Kayitli yapilandirma revizyonlari (ID, zaman, yonetici, surum, aciklama)","sev":"i"},{"cat":"Yedekleme","code":"execute restore config flash <revizyon-id>","desc":"Revizyondan geri yukler; cihaz YENIDEN BASLAR. Bakim penceresinde yapin","sev":"e"},{"cat":"Yedekleme","code":"execute restore config tftp <dosya> <tftp-sunucu>","desc":"TFTP'deki yedekten geri yukler; cihaz YENIDEN BASLAR. Yedek ayni model ve surumden olmali","sev":"e"},{"cat":"Config Gorunumu","code":"show firewall central-snat-map","desc":"Merkezi SNAT tablosu (config system settings / central-nat enable iken kullanilir). Ilk eslesen kayit gecerli","sev":"i"},{"cat":"Config Gorunumu","code":"show firewall ssl-ssh-profile","desc":"SSL/SSH inceleme profilleri: https status (certificate-inspection / deep-inspection), caname, ssl-exempt muafiyetleri","sev":"i"},{"cat":"Config Gorunumu","code":"show firewall schedule recurring","desc":"Tekrarlayan zamanlamalar (day, start, end). Kural 'beklenmedik saatte calismiyor' ise buraya ve cihaz saatine bakin","sev":"i"},{"cat":"Config Gorunumu","code":"show system sdwan","desc":"SD-WAN uyeleri, health-check ve kurallar (7.x'te 'system virtual-wan-link' yok)","sev":"i"},{"cat":"Config Gorunumu","code":"show system snmp user","desc":"SNMPv3 kullanicilari: security-level (auth-priv olmali), notify-hosts, auth/priv protokolleri","sev":"i"},{"cat":"Config Gorunumu","code":"show vpn certificate local","desc":"Cihazdaki yerel sertifikalar (SSL inceleme CA'si, Agentless VPN/IPsec sunucu sertifikasi)","sev":"i"},{"cat":"Config Gorunumu","code":"show user radius","desc":"RADIUS sunuculari: server, secret (ENC), require-message-authenticator (varsayilan enable, show'da gorunmez)","sev":"i"},{"cat":"Config Gorunumu","code":"show log fortianalyzer setting","desc":"FortiAnalyzer log gonderimi: status, server, upload-option, reliable. Baglanti testi: execute log fortianalyzer test-connectivity","sev":"i"},{"cat":"Config Gorunumu","code":"show system central-management","desc":"FortiManager baglantisi: type fortimanager, fmg adresi. Durum: diagnose fdsm central-mgmt-status","sev":"i"},{"cat":"Objects","code":"show firewall address IP_10.64.8.120/32","desc":"IP address nesnesi: subnet tipi, IP/mask. /32 = tek host. Policy'lerde srcaddr/dstaddr olarak kullanilir. Isim bosluk iceriyorsa tirnak icine alin","sev":"i"},{"cat":"Objects","code":"show firewall address intranet.example.com","desc":"FQDN address nesnesi: DNS ile cozumlenir, IP degisirse otomatik guncellenir. DNS sunucu dogru yapilandirilmis olmali","sev":"i"},{"cat":"Objects","code":"show firewall vip 203.0.113.50_10.64.1.153_5060_UDP","desc":"VIP (Virtual IP/DNAT): extip (WAN IP) -> mappedip (LAN IP). portforward=enable ise port bazli, disable ise 1:1 NAT. extport/mappedport farkli olabilir","sev":"i"},{"cat":"Users","code":"show user local","desc":"Lokal (FortiGate uzerinde tanimli) kullanicilar: isim, status (enable/disable), two-factor ayari, email. SSL VPN/admin kullanicilari burada","sev":"i"},{"cat":"Users","code":"show user fortitoken","desc":"FortiToken (2FA) ile eslesmis kullanicilar: token SN, status (active/locked), kullanici eslesmesi. Token locked ise admin reset etmeli","sev":"i"},{"cat":"Users","code":"show user ldap CORP\\ AD","desc":"LDAP sunucu konfigurasyonu: server IP/FQDN, port (389/636), cnid, dn, type (regular/simple), source-ip, secure (ldaps/starttls). Bosluklu isimler \\\\ ile escape edilir","sev":"i"},{"cat":"Users","code":"show user password-policy","desc":"Sifre politikasi: minimum uzunluk, karmasiklik gereksinimleri, expire-days, reuse-password. Compliance gereksinimleri icin","sev":"i"},{"cat":"Users","code":"diagnose user device list","desc":"FortiGate tarafindan tespit edilmis cihazlar: MAC, IP, OS tipi, device tipi. Device identification ozelligini kullanir. BYOD kontrolu icin","sev":"i"},{"cat":"Auth","code":"diagnose test authserver ldap <server> <user> <pass>","desc":"LDAP auth testi: succeeded=OK, failed=sifre yanlis, connect error=sunucuya ulasilamiyor. Sonucta grup uyelikleri de gorulur. Sifre musteriden istenir!","sev":"i"},{"cat":"Auth","code":"diagnose test authserver ldap LDAP_SRV1 <kullanici> <parola>","desc":"Gercek LDAP test ornegi. server_name = 'show user ldap' ciktisindaki isim. Sifre acik metin olarak yazilir — dikkatli olun!","sev":"w"},{"cat":"Auth","code":"diagnose test authserver radius <server> <type> <user> <pass>","desc":"RADIUS auth testi. type: chap/pap/mschap/mschap2. succeeded/failed/timeout donebilir. RADIUS shared secret'i kontrol edin","sev":"i"},{"cat":"Auth","code":"diagnose debug authd fsso list","desc":"FSSO ile authenticate olmus kullanicilar: IP, username, domain, grup uyelikleri. Total=0 ise FSSO calismiyor veya DC'ye ulasilamiyor","sev":"i"},{"cat":"Auth","code":"diagnose debug authd fsso server-status","desc":"FortiGate ve Domain Controller arasindaki FSSO agent baglanti durumu. Status connected=OK, disconnected=SORUN. IP ve port kontrol edin","sev":"i"},{"cat":"Auth","code":"diagnose debug authd fsso refresh-logons","desc":"FSSO kullanici bilgilerini DC'den tekrar cekmesini tetikler. Kullanici listesi guncel degilse veya eksik kullanicilar varsa kullanin","sev":"i"},{"cat":"Auth","code":"diagnose debug fsso-polling detail","desc":"FSSO polling modu detayi — FortiGate dogrudan DC'den event log okuyor. Poll suresi, okunan event sayisi, hatalar","sev":"i"},{"cat":"Auth","code":"diagnose debug fsso-polling summary","desc":"FSSO polling ozeti: son poll zamani, basarili/basarisiz poll sayisi, bagli DC listesi","sev":"i"},{"cat":"Auth","code":"diagnose debug fsso-polling user","desc":"FSSO polling ile tespit edilmis login olan kullanicilar listesi. Kullanici burada yoksa DC event log'unda gorunmuyor demektir","sev":"i"},{"cat":"Auth","code":"execute fsso refresh","desc":"FSSO kullanici tablosunu tamamen yeniler. Cache sifirlanir, tum kullanicilar DC'den tekrar alinir. Buyuk ortamda biraz surebilir","sev":"i"},{"cat":"Auth","code":"diagnose debug application fnbamd -1","desc":"Lokal auth daemon debug — FortiGate uzerindeki local/LDAP/RADIUS auth islemlerini gosterir. Auth failed detaylarini gormek icin","sev":"w"},{"cat":"Auth","code":"diagnose debug application authd -1","desc":"Remote auth daemon debug — FSSO, captive portal, policy-based auth islemlerini gosterir. Kullanici login surecini izlemek icin","sev":"w"},{"cat":"Auth","code":"diagnose debug application authd 8256","desc":"DC baglanti debug — ozellikle DC ile iletisim sorunlarini izlemek icin. 8256 seviyesi DC handshake detaylarini gosterir","sev":"w"},{"cat":"Auth","code":"diagnose debug application fssod -1","desc":"FSSO daemon debug — FSSO agent ile iletisim, kullanici logon/logoff event'leri. Agent-based FSSO sorunlari icin","sev":"w"},{"cat":"Auth","code":"diagnose debug application samld -1","desc":"SAML authentication debug — SAML IdP ile iletisim, assertion dogrulama, metadata exchange. SSO sorunlari icin","sev":"w"},{"cat":"Auth","code":"diagnose firewall auth filter <filter>","desc":"Auth filtresi ayarla — belirli IP veya kullanici icin auth durumunu kontrol etmek icin. Ardindan 'auth list' calistirin","sev":"i"},{"cat":"Auth","code":"diagnose firewall auth list","desc":"Firewall tarafindan authenticate olmus IPv4 kullanicilar: IP, username, grup, auth method, idle time. Policy-based auth kontrolu","sev":"i"},{"cat":"Auth","code":"diagnose wad user list","desc":"WAD (proxy engine) tarafindan authenticate olmus kullanicilar. Explicit proxy veya ZTNA proxy auth icin. wad user =/= firewall auth","sev":"i"},{"cat":"HA","code":"get system ha status","desc":"HA durumu: Health Status (OK/Critical), mode (A-P/A-A), master/slave seri no, cluster uptime, son state change, heartbeat interface durumu (up/down), CPU/memory/session ortalamalari, sync durumu (in-sync/out-of-sync)","sev":"i"},{"cat":"HA","code":"diagnose system ha status","desc":"Daha detayli HA bilgisi: uptime, monitored link failures, priority, override durumu. 'get' versiyonundan daha teknik cikti verir","sev":"i"},{"cat":"HA","code":"execute ha manage <kume-indeksi> <admin-adi>","desc":"Diger HA uyesinin (secondary) CLI'ina atlar. Iki arguman zorunlu: kume indeksi ve o cihazda oturum acacak yonetici adi. 'execute ha manage ?' indeksleri listeler. Atlayinca get system status ile seri no dogrulayin!","sev":"i"},{"cat":"HA","code":"diagnose sys ha checksum cluster","desc":"Her member'in konfig checksum'u: global ve VDOM bazli. Iki member'in checksum'lari AYNI olmali. Farkli ise out-of-sync — konfig eslesmiyordur","sev":"i"},{"cat":"HA","code":"diagnose sys ha checksum show <vdom>","desc":"Belirli VDOM veya 'global' icin detayli checksum — hangi config bolumunun farkli oldugunu gosterir. Out-of-sync root cause bulmak icin","sev":"i"},{"cat":"HA","code":"diagnose sys ha checksum recalculate","desc":"Checksum'lari yeniden hesaplar. Out-of-sync uyarisi varsa once bunu deneyin — genellikle zararsizdir ve sorunu cozebilir","sev":"w"},{"cat":"HA","code":"diagnose sys ha reset-uptime","desc":"HA member uptime'ini sifirlar — bu member'in priority'si duser ve failover tetiklenir (override disable ise). Kontrollü failover testi icin","sev":"w"},{"cat":"HA","code":"diagnose sys ha history read","desc":"HA gecmis olaylari: failover tarihleri, sebepleri, state degisiklikleri. Neden failover oldugunu anlamak icin ilk bakilacak yer","sev":"i"},{"cat":"HA","code":"execute ha synchronize stop","desc":"HA config senkronizasyonunu durdurur. Debug amacli — stop, debug ac, start sirasiyla verbose cikti alinir. Uzun sure acik BIRAKMAYIN!","sev":"e"},{"cat":"HA","code":"execute ha synchronize start","desc":"HA config senkronizasyonunu baslatir. stop ile durdurulduysa tekrar baslatin. Config sync olmadan master/slave farkli calisir!","sev":"ok"},{"cat":"HA","code":"diagnose debug application hatalk -1","desc":"HA heartbeat iletisimi debug — member'lar arasi heartbeat paketleri. state=work (normal), chg_time=son failover zamani. Heartbeat interface sorunlari icin","sev":"w"},{"cat":"HA","code":"diagnose debug application hasync -1","desc":"HA senkronizasyon debug — config/session sync islemleri. Ilk sync sonrasi cikti gelmeyebilir (sync tamamlanmissa). Out-of-sync sorunlari icin","sev":"w"},{"cat":"HA","code":"diagnose debug application harelay -1","desc":"HA relay debug — cluster member'lar arasi komut/veri iletimi. execute ha manage ile yapilan islemlerin relay mekanizmasi","sev":"w"},{"cat":"UTM","code":"show webfilter profile WF_KISITLI","desc":"Web filter profil konfigi: ftgd-wf (FortiGuard kategori filtreleme), url-filter (URL bazli), content-filter, override ayarlari. Policy'de hangi profil atanmis kontrol icin","sev":"i"},{"cat":"UTM","code":"show application list APP_KISITLI","desc":"Application Control profili: hangi uygulamalar block/monitor/allow. Kategori bazli (social-media, p2p, gaming) veya uygulama bazli (WhatsApp, BitTorrent) kurallar","sev":"i"},{"cat":"UTM","code":"show dlp sensor CORP_DLP","desc":"DLP (Data Loss Prevention) sensor konfigi: kredi karti, TC kimlik, custom regex pattern'ler. Hassas veri sizintisi onleme kurallari","sev":"i"},{"cat":"UTM","code":"diagnose debug application urlfilter -1","desc":"Web filter debug — URL kategori sorgulari, FortiGuard rating sonuclari, block/allow kararlari. Neden bir site engelleniyor anlamak icin","sev":"w"},{"cat":"UTM","code":"diagnose test application urlfilter","desc":"Web filter test secenekleri menusu — belirli URL'yi test etme, cache durumu, istatistikler. Numara girerek secenek calistirin","sev":"i"},{"cat":"UTM","code":"diagnose debug application dnsproxy -1","desc":"DNS proxy debug — DNS sorgu/yanit islemleri, DNS filtreleme kararlari. DNS bazli sorunlarda (domain cozumlenemiyor, yanlis IP donuyor)","sev":"w"},{"cat":"UTM","code":"diagnose test application dnsproxy","desc":"DNS proxy test menusu — DNS cache, forwarding, statistics. Numara ile test calistirin. Cache flush icin de kullanilir","sev":"i"},{"cat":"IPS","code":"diagnose ips filter set \"host <x.x.x.x> and port <port>\"","desc":"IPS debug filtresi — tcpdump syntax. Belirli IP/port icin IPS engine davranisini izlemek icin. Filtresiz cok yogun cikti!","sev":"i"},{"cat":"IPS","code":"diagnose ips debug enable all","desc":"TUM IPS engine debug'unu acar — signature match, protocol decode, action (block/pass/reset). CPU yogun! Kisa sureli kullanin","sev":"w"},{"cat":"IPS","code":"diagnose ips debug enable av","desc":"Sadece antivirus debug'unu acar — dosya tarama, virus tespit, karantina islemleri. Dosya download sorunlarinda","sev":"w"},{"cat":"IPS","code":"diagnose ips debug status show","desc":"Aktif IPS debug ayarlarini gosterir — hangi modullerin debug'u acik","sev":"i"},{"cat":"IPS","code":"diagnose ips session list","desc":"IPS engine tarafindan islenen aktif session'lar. Session bazli IPS detaylari: signature match durumu, inspection modu","sev":"i"},{"cat":"IPS","code":"diagnose test application ipsmonitor 1","desc":"IPS engine durum bilgisi: running/not running, instance sayisi, her instance'in rolu (IPS/AV). 'not running' ise acil restart gerekir","sev":"i"},{"cat":"IPS","code":"diagnose test application ipsmonitor 99","desc":"Tum IPS engine'leri yeniden baslatir. IPS crash veya donma durumunda kullanin. Kisa sureli inspection kesintisi olur. 97=start, 98=stop da var","sev":"e"},{"cat":"WAD","code":"diagnose test application wad 1000","desc":"Tum WAD (Web Application Detection) worker process'leri listeler. Her worker'in PID, CPU, memory kullanimi. Proxy inspection engine'i","sev":"i"},{"cat":"WAD","code":"diagnose test application wad 2","desc":"WAD toplam bellek kullanimi. Proxy-based inspection aktifse WAD onemli miktarda memory tuketir. Memory sorunu teshisi icin","sev":"i"},{"cat":"WAD","code":"diagnose test application wad 99","desc":"TUM WAD process'leri restart. Proxy-based inspection gecici olarak DURUR. SSL inspection, explicit proxy etkilenir. Son care olarak","sev":"e"},{"cat":"WAD","code":"diagnose wad debug display pid enable","desc":"WAD debug ciktisinda worker PID'sini gosterir. Birden fazla worker varsa hangi worker'in logunu gordugunuzu anlamak icin","sev":"i"},{"cat":"WAD","code":"diagnose wad filter <filter>","desc":"WAD debug filtresi: src/dst IP, port, policy bazli. Proxy inspection sorunlarini belirli trafik icin izlemek icin","sev":"i"},{"cat":"WAD","code":"diagnose wad filter list","desc":"Aktif WAD filtrelerini goster. Yeni filtre eklemeden once mevcut filtreleri kontrol edin","sev":"i"},{"cat":"WAD","code":"diagnose wad filter clear","desc":"Tum WAD filtrelerini temizler. Debug sonrasi MUTLAKA calistirin","sev":"ok"},{"cat":"SD-WAN","code":"diagnose sys sdwan health-check status","desc":"Health check sonuclari: state (alive/dead), packet-loss (%), latency (ms), jitter (ms), sla_map (SLA eslesmesi). dead=link down veya SLA karsilamiyor","sev":"i"},{"cat":"SD-WAN","code":"diagnose sys sdwan service4","desc":"SD-WAN IPv4 kurallari: hangi trafik hangi member'a yonlendirilir, strategy (manual/best-quality/lowest-cost), member durumu ve secimi","sev":"i"},{"cat":"SD-WAN","code":"diagnose sys sdwan service6","desc":"SD-WAN IPv6 kurallari — IPv4 ile ayni format. IPv6 SD-WAN trafik yonlendirme kurallari","sev":"i"},{"cat":"SD-WAN","code":"diagnose sys sdwan member","desc":"SD-WAN member'lari: interface, gateway, priority, weight, volume ratio, session sayisi. Member status alive/dead. Weight dagilima gore trafik orani belirlenir","sev":"i"},{"cat":"SD-WAN","code":"diagnose firewall proute list","desc":"SD-WAN policy route listesi — SD-WAN aktifse burada SD-WAN kurallari gorulur. used=0 ise kural eslesmiyor. Normal routing'den ONCE uygulanir","sev":"i"},{"cat":"SD-WAN","code":"diagnose sys link-monitor status","desc":"Link monitoring (SD-WAN olmadan da calisir): her link'in durumu, latency, jitter. WAN link kalitesi izleme","sev":"i"},{"cat":"SD-WAN","code":"diagnose sys link-monitor interface <interface>","desc":"Belirli interface'in link monitor detayi: health check hedefi, son kontrol zamani, ortalama latency/loss","sev":"i"},{"cat":"SD-WAN","code":"diagnose debug application link-monitor -1","desc":"Link monitor debug — probe gonderme/alma, durum degisiklikleri (alive->dead/dead->alive). SD-WAN failover sorunlari icin","sev":"w"},{"cat":"FEXT","code":"get system interface physical","desc":"FEXT interface'lerin fiziksel durumu. FortiGate'den bagimsiz olarak FEXT uzerindeki interface'leri gosterir","sev":"i"},{"cat":"FEXT","code":"get system interface","desc":"FEXT uzerindeki tum interface'ler: LTE modem, WAN, LAN portlari. IP adresi ve status bilgisi","sev":"i"},{"cat":"FEXT","code":"get system arp","desc":"FEXT ARP tablosu — LAN tarafindaki cihazlarin MAC/IP eslesmesi. FEXT arkasindaki cihaz erisim kontrolu icin","sev":"i"},{"cat":"FEXT","code":"execute ping 192.0.2.5","desc":"FEXT'ten uzak hedefe ping. FEXT'in WAN/LTE erisimini dogrulamak icin. FortiGate'den FEXT uzerinden ping farkli sonuc verebilir","sev":"i"},{"cat":"FEXT","code":"execute dhcp lease-list","desc":"FEXT DHCP server lease listesi: kimlere IP verilmis, lease suresi, MAC adresi. FEXT LAN tarafindaki cihaz envanteri","sev":"i"},{"cat":"FEXT","code":"execute telnet 192.0.2.5","desc":"FEXT'ten uzak cihaza telnet. CPE/modem yonetimi icin. FEXT uzerinden L3 erisim testi","sev":"i"},{"cat":"FEXT","code":"get system status","desc":"FEXT firmware versiyonu, model, seri no, uptime. FortiGate'in 'get system status'undan farkli — FEXT'in kendi durumu","sev":"i"},{"cat":"FEXT","code":"get extender status","desc":"Extender baglanti durumu: connected/disconnected, sinyal gucu (dBm), operator (Turkcell/Vodafone), teknoloji (LTE/3G). -50/-75=iyi, -75/-90=zayif, >-90=kotu","sev":"i"},{"cat":"FEXT","code":"get system version","desc":"FEXT firmware versiyonu. Guncelleme gerekip gerekmedigi kontrolu icin. FortiGate ile uyumlu versiyon olmali","sev":"i"},{"cat":"FEXT","code":"config lte plan","desc":"LTE data plan konfigurasyonu: APN, monthly limit, overage action. 'show' ile mevcut plani gorun, 'set' ile degistirin","sev":"i"},{"cat":"FEXT","code":"execute reboot","desc":"FEXT'i yeniden baslatir. LTE baglantisi KESILIR! Modem donma, sinyal sorunu sonrasi kullanin. FortiGate uzerinden de yapilabilir","sev":"e"},{"cat":"FEXT","code":"execute exit","desc":"FEXT CLI'dan cikar ve FortiGate CLI'a doner. FEXT'e FortiGate uzerinden execute extender-cli <FEXT_SN> ile girilir","sev":"i"},{"cat":"Logging","code":"diagnose log test","desc":"Her kategoriden (traffic, event, utm) birer test log uretir. Log pipeline'in calistigini dogrulamak icin. FAZ/syslog'a ulasiyorsa OK","sev":"i"},{"cat":"Logging","code":"execute log filter <filter>","desc":"Log filtreleme: category (traffic/event/utm), field (srcip/dstip/action/etc), view-lines (satir sayisi), start-line, device (memory/disk/fortianalyzer)","sev":"i"},{"cat":"Logging","code":"execute log filter","desc":"Aktif log filtrelerini gosterir. Filtre yoksa tum loglar gorulur. Her yeni arama oncesi filtreleri temizleyin","sev":"i"},{"cat":"Logging","code":"exec log display","desc":"Filtrelenmis loglari CLI'da gosterir. Her log satiri: date, time, logid, type, subtype, level, srcip, dstip, action, policyid bilgileri icerir","sev":"i"},{"cat":"Logging","code":"execute log delete","desc":"Filtreye uyan loglari SILER. Disk/memory uzerindeki loglar icin gecerli. FAZ'daki loglar etkilenmez. GERI ALINAMAZ!","sev":"e"},{"cat":"Logging","code":"execute log fortianalyzer test-connectivity","desc":"FAZ baglanti testi: Registration (registered/unregistered), Connection (allow/deny), OFTP session (connected/disconnected). Tum satirlar OK olmali","sev":"i"},{"cat":"Logging","code":"show log syslogd setting","desc":"Syslog konfigurasyonu: server IP, port (default 514), facility, format (default/csv/cef), source-ip, status (enable/disable). Loglar syslog'a gidiyor mu kontrolu","sev":"i"},{"cat":"Logging","code":"show log syslogd override-setting","desc":"VDOM bazli syslog override ayarlari. Multi-VDOM ortaminda her VDOM farkli syslog sunucusuna gonderebilir","sev":"i"},{"cat":"Logging","code":"diagnose debug application miglogd -1","desc":"Log daemon debug — log yazma, FAZ/syslog gonderme islemleri. Log kaybi veya gecikme sorunlarinda. -1=maximum verbosity","sev":"w"},{"cat":"FortiSwitch","code":"diagnose switch-controller switch-info mac-table","desc":"FortiSwitch MAC tablosu: port, VLAN, MAC, type (dynamic/static). Hangi cihaz hangi porta bagli gormek icin. Cihaz bulunamazsa burada kontrol edin","sev":"i"},{"cat":"FortiSwitch","code":"diagnose switch-controller switch-info port-stats","desc":"Port istatistikleri: Rx/Tx packets/bytes, errors, drops, CRC. Errors/CRC>0 ise fiziksel sorun (kablo/port). High drops ise congestion","sev":"i"},{"cat":"FortiSwitch","code":"diagnose switch-controller switch-info trunk status","desc":"Trunk (LAG/LACP) durumu: up/down, member portlar, LACP state. Trunk down ise member portlarin link durumunu kontrol edin","sev":"i"},{"cat":"FortiSwitch","code":"diagnose switch-controller switch-info stp","desc":"STP durumu: port state (forwarding/blocking/disabled), root bridge, path cost. Blocking state ise loop onleme aktif veya topoloji sorunu","sev":"i"},{"cat":"FortiSwitch","code":"diagnose switch-controller switch-info poe","desc":"PoE durumu: port, power (W), max, status (delivering/searching/disabled). Budget asilmissa yeni cihazlara guc verilmez","sev":"i"},{"cat":"FortiSwitch","code":"diagnose switch-controller switch-info lldp","desc":"LLDP bilgisi: komsu cihaz adi, port, model. Topoloji kesfetme icin. Yanlis kablolama tespiti","sev":"i"},{"cat":"FortiSwitch","code":"diagnose switch-controller switch-info igmp-snooping","desc":"IGMP snooping: multicast group, port uyelikleri. IPTV/multicast sorunlarinda hangi portun hangi gruba uye oldugu kontrolu","sev":"i"},{"cat":"FortiSwitch","code":"diagnose switch-controller switch-info 802.1X","desc":"802.1X NAC durumu: port, auth status (authorized/unauthorized), kullanici. Unauthorized ise RADIUS/cert sorunu olabilir","sev":"i"},{"cat":"FortiSwitch","code":"execute switch-controller get-conn-status <SN>","desc":"FortiSwitch baglanti durumu (SN=seri numarasi): connected/disconnected, firmware, model. FortiLink kopuklugu kontrolu","sev":"i"},{"cat":"FortiSwitch","code":"execute switch-controller diagnose-connection <SN>","desc":"FortiSwitch baglanti teshisi: FortiLink interface, authorization, management tunnel durumu. Detayli troubleshoot icin","sev":"i"},{"cat":"FortiSwitch","code":"diagnose netlink brctl list","desc":"FortiGate dahili software switch'leri: internal, lan gibi. Bridge interface'lerin member portlarini ve durumlarini gosterir","sev":"i"},{"cat":"FortiSwitch","code":"diagnose netlink brctl name host <switch-name>","desc":"Belirli software switch'in forwarding (MAC) tablosu: MAC, port, age. L2 trafik yonlendirme kontrolu icin","sev":"i"},{"cat":"FortiGuard","code":"diagnose autoupdate status","desc":"FortiGuard guncelleme durumu: son guncelleme zamani, sonraki planlanan guncelleme, baglanti durumu. 'Unreachable' ise internet/DNS kontrol edin","sev":"i"},{"cat":"FortiGuard","code":"diagnose autoupdate versions","desc":"Lisans ve veritabani bilgileri: AV, IPS, App Control, Web Filter veritabani tarihleri. Expired lisanslar UTM ozelliklerini devre disi birakir","sev":"i"},{"cat":"FortiGuard","code":"execute update-now","desc":"Manual FortiGuard guncelleme tetikler. AV/IPS/App imzalari hemen guncellenir. Internet erisimi gerektirir (update.fortiguard.net)","sev":"i"},{"cat":"FortiGuard","code":"diagnose webfilter fortiguard statistics","desc":"Web filter rating cache istatistikleri: cache hit/miss, rating daemon durumu. Yuksek miss orani DNS/baglanti sorununa isaret edebilir","sev":"i"},{"cat":"FortiGuard","code":"diagnose debug rating","desc":"FortiGuard web rating sunucu bilgisi: hangi rating sunucuya baglaniliyor, latency, durum. Web filter yavasliginda kontrol edin","sev":"i"},{"cat":"SIP","code":"diagnose sys sip status","desc":"SIP ALG (Application Layer Gateway) durumu: aktif session sayisi, session helper modu. VoIP sorunlarinda ilk kontrol noktasi","sev":"i"},{"cat":"SIP","code":"diagnose sys sip mapping list","desc":"SIP NAT mapping listesi: ic/dis IP:port eslesmesi. SIP cihazi NAT arkasindaysa mapping dogru mu kontrolu. Tek yonlu ses sorunlarinda bakin","sev":"i"},{"cat":"SIP","code":"diagnose sys sip dialog list","desc":"Aktif SIP diyalog/cagri listesi: Call-ID, from/to, state. Aktif VoIP cagrilarini gormek icin","sev":"i"},{"cat":"SIP","code":"diagnose debug application sip -1","desc":"SIP ALG debug — SIP mesaj islemleri, NAT cevirisi, header modifikasyonu. Tek yonlu ses, cagri kurulamama sorunlarinda. Yogun cikti!","sev":"w"},{"cat":"SIP","code":"diagnose sys sip-proxy calls list","desc":"SIP proxy modundaki aktif cagrilar. Session-helper degil proxy modu kullaniliyorsa bu komut gecerli","sev":"i"},{"cat":"SIP","code":"diagnose sys sip-proxy stats","desc":"SIP proxy istatistikleri: toplam cagri, basarili/basarisiz, aktif cagri sayisi","sev":"i"},{"cat":"SIP","code":"diagnose sys sip-proxy session list","desc":"SIP proxy session listesi: her session'in detayli bilgisi, media (RTP) port eslesmesi","sev":"i"},{"cat":"ZTNA","code":"diagnose endpoint fctems test-connectivity <EMS>","desc":"FortiClient EMS baglanti testi: EMS sunucusuna TCP erisim, sertifika dogrulama. ZTNA calisabilmesi icin EMS baglantisi sart","sev":"i"},{"cat":"ZTNA","code":"execute fctems verify <EMS>","desc":"EMS sertifika dogrulama: sertifika zinciri gecerli mi kontrol eder. Sertifika hatasi ZTNA'yi kirar","sev":"i"},{"cat":"ZTNA","code":"diagnose test application fcnacd 2","desc":"FortiClient NAC daemon — EMS baglanti detaylari: IP, port, durum, son sync zamani. ZTNA tag senkronizasyonu kontrolu","sev":"i"},{"cat":"ZTNA","code":"diagnose firewall dynamic list","desc":"ZTNA security posture tag'leri: EMS'den alinan endpoint durumu tag'leri. Policy'lerde ZTNA tag eslesme kontrolu icin","sev":"i"},{"cat":"Shaping","code":"diagnose firewall shaper traffic-shaper list","desc":"Tanimli traffic shaper'lar: isim, guaranteed/maximum bandwidth (kbps), priority, per-policy. Bant genisligi yonetimi kontrolu","sev":"i"},{"cat":"Shaping","code":"diagnose firewall shaper traffic-shaper stats list","desc":"Traffic shaper istatistikleri: current bandwidth, drop sayisi, queued packets. Drop yuksekse shaper limiti yetersiz","sev":"i"},{"cat":"Profiling","code":"diagnose sys profile cpumask <cpu_id>","desc":"Profil icin CPU core secimi. cpu_id: 0=ilk core. Belirli core'da bottleneck analizi icin","sev":"i"},{"cat":"Profiling","code":"diagnose sys profile start","desc":"CPU profiling baslatir — kernel fonksiyonlarinin ne kadar sure harcadigini olcer. Performans analizi icin. CPU yuklenir!","sev":"w"},{"cat":"Profiling","code":"diagnose sys profile stop","desc":"CPU profiling durdurur. Ardindan 'show detail/order' ile sonuclari gorun","sev":"ok"},{"cat":"Profiling","code":"diagnose sys profile module","desc":"Kernel modulleri ve CPU kullanim dagilimlari. Hangi modul (networking, crypto, etc.) en cok CPU kullaniyor","sev":"i"},{"cat":"Profiling","code":"diagnose sys profile show detail","desc":"Detayli profil sonuclari: her fonksiyonun harcadigi CPU suresi. Performans bottleneck root cause analizi. TAC'a gondermek icin","sev":"i"},{"cat":"LDAP","code":"edit LDAP_SRV1","desc":"'config user ldap' icerisinde: LDAP sunucu duzenleme. LDAP_SRV1 = sunucu konfigurasyondaki isim. Tab ile otomatik tamamlama","sev":"i"},{"cat":"LDAP","code":"set source-ip 10.128.0.2","desc":"LDAP sorgularinda kullanilacak kaynak IP. Multi-interface ortamda LDAP sunucusuna dogru interface'den cikmayi saglar. Routing/firewall source-ip eslesmeli","sev":"i"},{"cat":"FortiAP","code":"diagnose wireless-controller wlac -c wtp","desc":"FortiAP cihaz listesi: SN, model, IP, state (online/offline/rogue), uptime, firmware. Bagli AP'lerin genel durumu","sev":"i"},{"cat":"FortiAP","code":"diagnose wireless-controller wlac -d wtp","desc":"FortiAP detayli bilgi: her AP'nin tum konfigurasyonu, radio ayarlari, kanal, guc, client sayisi","sev":"i"},{"cat":"FortiAP","code":"diagnose wireless-controller wlac -c sta","desc":"Bagli wireless client listesi: MAC, IP, SSID, signal, AP adi, VLAN, bandwidth","sev":"i"},{"cat":"FortiAP","code":"diagnose wireless-controller wlac -d sta","desc":"Wireless client detayli bilgi: her client'in baglanti detaylari, SNR, data rate, channel","sev":"i"},{"cat":"FortiAP","code":"diagnose wireless-controller wlac help","desc":"Wireless controller debug secenekleri listesi. Tum alt komutlari gosterir","sev":"i"},{"cat":"FortiAP","code":"diagnose wireless-controller wlac sta_filter <mac> 255","desc":"Belirli client MAC'ine debug filtresi koy. Sadece bu client'in debug ciktisi gorulur","sev":"i"},{"cat":"FortiAP","code":"diagnose wireless-controller wlac sta_filter clear","desc":"Client debug filtresini temizle","sev":"ok"},{"cat":"FortiAP","code":"diagnose wireless-controller wlac wtp_filter <SN> 0-<ip>:5246 255","desc":"Belirli AP'ye debug filtresi. SN=AP seri numarasi, IP=AP IP. Sadece bu AP'nin debug ciktisi","sev":"i"},{"cat":"FortiAP","code":"diagnose wireless-controller wlac wtp_filter clear","desc":"AP debug filtresini temizle","sev":"ok"},{"cat":"FortiAP","code":"diagnose wireless-controller wlac -c vap","desc":"VAP (Virtual Access Point) listesi: SSID'ler, VLAN, security mode, bagli client sayisi","sev":"i"},{"cat":"FortiAP","code":"diagnose debug application cw_acd 0x7ff","desc":"Wireless controller daemon debug baslat. AP discovery, join, konfigurasyonu izleme. Cok yogun cikti!","sev":"w"},{"cat":"FortiAP","code":"diagnose debug application cw_acd 0","desc":"Wireless controller debug'u kapat","sev":"ok"},{"cat":"FortiAP","code":"config wireless-controller wtp","desc":"FortiAP konfigurasyonu: authorize, firmware, radio ayarlari. 'edit <SN>' ile belirli AP secilir","sev":"i"},{"cat":"FortiAP","code":"config wireless-controller vap","desc":"VAP (SSID) konfigurasyonu: SSID adi, security (wpa2/wpa3), VLAN, schedule, rate-limit","sev":"i"},{"cat":"FortiAP","code":"config wireless-controller wtp-profile","desc":"AP profil konfigurasyonu: radio1/radio2, kanal, guc, band (2.4/5GHz), DTIM, beacon interval","sev":"i"},{"cat":"FortiAP","code":"execute wireless-controller restart-acd","desc":"Wireless controller daemon restart. TUM AP'ler gecici olarak kopar ve yeniden baglanir!","sev":"e"},{"cat":"FortiAP","code":"get wireless-controller wtp-status","desc":"FortiAP durum ozeti: authorize edilmis AP sayisi, online/offline/rogue sayilari","sev":"i"},{"cat":"Multicast","code":"get router info multicast igmp interface","desc":"IGMP interface istatistikleri: hangi interface'lerde IGMP aktif, join/leave sayilari, query interval. Multicast routing teshisi","sev":"i"},{"cat":"Multicast","code":"get router info multicast igmp groups","desc":"Uye olunan multicast gruplari: grup adresi (224.x.x.x), interface, uye sayisi. IPTV/video streaming sorunlarinda","sev":"i"},{"cat":"Multicast","code":"get router info multicast pim sparse-mode rp-mapping","desc":"PIM RP (Rendezvous Point) eslemesi: hangi multicast grubunun RP'si kim. RP erisimi yoksa multicast calismaz","sev":"i"},{"cat":"Multicast","code":"get router info multicast pim sparse-mode table","desc":"PIM sparse-mode routing tablosu: (S,G) ve (*,G) kayitlari. Multicast trafik akisinin yolunu gosterir","sev":"i"}],"scenarios":[{"title":"IPsec VPN Tunnel Gelmiyorsa","severity":"err","symptom":"VPN tunnel UP olmuyor, Phase 1 veya Phase 2 kurulmuyor.","steps":[{"code":"get vpn ipsec tunnel summary","desc":"Tunnel durumunu kontrol et"},{"code":"diagnose vpn ike gateway list name <tunnel_name>","desc":"Phase 1 (IKE) durumunu incele"},{"code":"diagnose vpn tunnel list name <tunnel_name>","desc":"Phase 2 durumunu incele"},{"code":"diagnose vpn ike log filter rem-addr4 <peer_ip>","desc":"IKE debug icin karsi uc IP filtresi koy (eski surumlerde, 7.2 dahil: log-filter dst-addr4)"},{"code":"diagnose debug application ike -1","desc":"IKE debug baslat"},{"code":"diagnose debug enable","desc":"Debug ciktisini etkinlestir"},{"code":"diagnose sniffer packet any 'host <peer_ip> and port 500' 4 0 1","desc":"IKE trafigini sniffer ile kontrol et"}]},{"title":"SSL VPN Kullanicisi Baglanamiyorsa","severity":"warn","symptom":"SSL VPN kullanicisi portal'a ulasamiyor veya tunnel kurulamiyor.","steps":[{"code":"get vpn ssl monitor","desc":"Bagli kullanicilari kontrol et"},{"code":"get vpn ssl settings","desc":"SSL VPN ayarlarini kontrol et (port, interface)"},{"code":"diagnose vpn ssl list","desc":"SSL VPN session'lari listele"},{"code":"diagnose debug application sslvpn -1","desc":"SSL VPN debug baslat"},{"code":"diagnose debug enable","desc":"Debug etkinlestir"},{"code":"diagnose firewall auth list","desc":"Kullanici auth durumunu kontrol et"}]},{"title":"Yuksek CPU Kullanimi","severity":"err","symptom":"Cihaz yavasliyor, CPU %80+ gosteriyor.","steps":[{"code":"get system performance status","desc":"CPU/memory ozeti"},{"code":"diagnose sys top","desc":"En cok CPU kullanan process"},{"code":"diagnose sys top-summary","desc":"Process ozeti"},{"code":"get system session status","desc":"Toplam session sayisi"},{"code":"diagnose sys mpstat 1","desc":"Core bazli CPU kullanimi"},{"code":"diagnose firewall packet distribution","desc":"Paket dagilimi"}]},{"title":"Trafik Gecmiyorsa (Debug Flow)","severity":"err","symptom":"Kullanici internete cikamiyorsa veya belirli hedefe ulasamiyorsa.","steps":[{"code":"diagnose debug flow filter addr <kaynak_ip>","desc":"Kaynak IP filtresi koy"},{"code":"diagnose debug flow show function-name enable","desc":"Fonksiyon adlarini goster"},{"code":"diagnose debug enable","desc":"Debug etkinlestir"},{"code":"diagnose debug flow trace start 100","desc":"100 satir debug al"},{"code":"diagnose debug disable","desc":"Bitince debug kapat"},{"code":"diagnose debug flow filter clear","desc":"Filtreleri temizle"}]},{"title":"HA Failover / Gecis Testi","severity":"warn","symptom":"HA cluster'da master/slave gecisi yapilmak isteniyor veya sorun var.","steps":[{"code":"get system status","desc":"Seri numarasi ile hangi cihazda oldugunuzu dogrulayin"},{"code":"get system ha status","desc":"HA durum bilgisi"},{"code":"execute ha manage <kume-indeksi> <admin-adi>","desc":"Diger uyeye atla ('execute ha manage ?' indeksleri listeler)"},{"code":"get system status","desc":"Yedek cihazin seri numarasini dogrulayin"},{"code":"config system interface","desc":"Interface config moduna girin"},{"code":"edit wan1","desc":"wan1 interface'ini secin"},{"code":"set status down","desc":"Interface'i DOWN yapin (failover tetiklenir)"},{"code":"set status up","desc":"Interface'i tekrar UP yapin"}]},{"title":"Routing Sorunu — Trafik Yanlis Yoldan Gidiyorsa","severity":"warn","symptom":"Trafik beklenmeyen interface'den cikiyor veya hedefe ulasamiyor.","steps":[{"code":"get router info routing-table all","desc":"Tam routing tablosuna bak"},{"code":"get router info routing-table database","desc":"Routing veritabanini kontrol et"},{"code":"get router info kernel","desc":"Kernel routing tablosuna bak"},{"code":"diagnose firewall proute list","desc":"Policy route (PBR/SD-WAN) kontrol et"},{"code":"diagnose ip rtcache list","desc":"Route cache kontrol et"},{"code":"diagnose ip route list","desc":"IP route listesi"},{"code":"show router static","desc":"Statik route konfigurasyonu"}]},{"title":"Session / Baglanti Sorunlari","severity":"warn","symptom":"Belirli IP veya servis icin baglanti kurulamiyor / kesiyor.","steps":[{"code":"get system session status","desc":"Session sayisi kontrol (limit asildiysa sorun)"},{"code":"diagnose sys session filter dst <hedef_ip>","desc":"Hedef IP icin session filtrele"},{"code":"diagnose sys session list","desc":"Filtrelenmis session'lari goster"},{"code":"diagnose sniffer packet any 'host <ip>' 4 0","desc":"Trafik var mi sniffer ile kontrol"},{"code":"diagnose debug flow filter addr <ip>","desc":"Debug flow ile paket izle"},{"code":"diagnose debug flow trace start 50","desc":"50 satir debug al"}]},{"title":"FortiAnalyzer Baglanti Sorunu","severity":"info","symptom":"Loglar FortiAnalyzer'a gitmiyor.","steps":[{"code":"execute log fortianalyzer test-connectivity","desc":"FAZ baglanti testi"},{"code":"show log syslogd setting","desc":"Syslog ayarlarini kontrol et"},{"code":"diagnose debug application miglogd -1","desc":"Logging debug baslat"},{"code":"diagnose debug enable","desc":"Debug etkinlestir"}]},{"title":"LDAP Authentication Testi","severity":"info","symptom":"LDAP kullanici dogrulama calismiyorsa.","steps":[{"code":"diagnose test authserver ldap <server_name> <username> <password>","desc":"LDAP sunucusuna test sorgusu"},{"code":"show user ldap","desc":"LDAP konfig kontrol"},{"code":"diagnose debug application fnbamd -1","desc":"Auth debug baslat"},{"code":"diagnose debug enable","desc":"Debug etkinlestir"}]},{"title":"Sniffer ile Paket Yakalama","severity":"info","symptom":"Trafik akisini anlamak icin paket yakalama gerekiyorsa.","steps":[{"code":"diagnose sniffer packet any 'host <ip>' 4 0","desc":"Temel: IP bazli yakalama"},{"code":"diagnose sniffer packet any 'host <ip> and port 443' 4 0","desc":"IP + Port filtreli"},{"code":"diagnose sniffer packet any 'src host <src_ip> and dst host <dst_ip>' 4 a","desc":"Kaynak+Hedef filtreli (absolute timestamp)"},{"code":"diagnose sniffer packet any 'host <ip>' 6","desc":"Verbose 6: hex+ascii detay"}]}],"sources":{},"links":[{"name":"Fortigate-Firewall-Complete-Guide","url":"https://github.com/hegdepavankumar/Fortigate-Firewall-Complete-Guide","desc":"En kapsamli rehber. Interface'den VPN'e kadar her seyi kapsiyor."},{"name":"yuriskinfo/cheat-sheets","url":"https://github.com/yuriskinfo/cheat-sheets","desc":"FortiGate debug/diagnose komutlarinin tam listesi (AsciiDoc)."},{"name":"yuriskinfo/Fortinet-tools","url":"https://github.com/yuriskinfo/Fortinet-tools","desc":"Gunluk konfigurasyon/debug/monitoring araclari ve scriptler."},{"name":"jeffbildz/Fortinet Cheat Sheet","url":"https://github.com/jeffbildz/Fortinet/blob/main/Fortinet_Cheat_Sheet.md","desc":"FortiGate + FortiSwitch CLI komutlari."},{"name":"GhostKellz/fortigate","url":"https://github.com/GhostKellz/fortigate/blob/main/CHEATSHEET.md","desc":"Otomasyon ve CLI referansi."},{"name":"oelu/cheatsheets (fortigate.md)","url":"https://github.com/oelu/cheatsheets/blob/master/fortigate.md","desc":"VPN, OSPF, debug flow dahil cheat sheet."},{"name":"ondrejholecek/fortidebug","url":"https://github.com/ondrejholecek/fortidebug","desc":"SSH uzerinden FortiGate troubleshoot araclari (simdi FortiLightHouse CLI)."},{"name":"malwan23/FG-CLI","url":"https://github.com/malwan23/FG-CLI","desc":"REST API uzerinden FortiGate yonetim araci."},{"name":"rrrrrrri/fgt-gadgets","url":"https://github.com/rrrrrrri/fgt-gadgets","desc":"FortiGate yardimci araclar."},{"name":"henri's FortiGate CLI Gist","url":"https://gist.github.com/henri/75aacdcc8dbaa815b275385b6ac87383","desc":"Fortigate Command Line Cheat Sheet (Gist)."},{"name":"cetinajero's Useful CLI Gist","url":"https://gist.github.com/cetinajero/1effb04ee9ae9fc6f65faaf43d4bff9b","desc":"Useul Fortigate CLI commands."},{"name":"Fortinet Resmi CLI Cheat Sheet (7.6)","url":"https://docs.fortinet.com/document/fortigate/7.6.0/cli-troubleshooting-cheat-sheet/420966/cli-troubleshooting-cheat-sheet","desc":"Resmi dokumanasyon — CLI troubleshooting referansi."},{"name":"Tuncay Bas — FortiGate Yararli Komutlar","url":"https://www.tuncaybas.com/index.php/fortigate-yararli-komutlar/","desc":"Turkce FortiGate CLI komut referansi."},{"name":"Cemal Taner — FortiGate CLI Rehberi","url":"https://www.korvo.co/cemaltaner/digital-products/4325","desc":"Kapsamli Turkce FortiGate CLI rehberi (ucretli)."},{"name":"Fortinet Community — Sniffer Kullanimi","url":"https://community.fortinet.com/t5/FortiGate/Troubleshooting-Tip-Using-the-FortiOS-built-in-packet-sniffer/ta-p/196856","desc":"Resmi sniffer kullanim rehberi."},{"name":"Fortinet Docs — Debug Flow","url":"https://docs.fortinet.com/document/fortigate/6.4.5/administration-guide/54688/debugging-the-packet-flow","desc":"Resmi debug flow rehberi."},{"name":"cmdref.net — FortiGate CLI","url":"https://cmdref.net/hardware/fortigate/index.html","desc":"Hizli CLI referansi ve ornekler."},{"name":"defencedev.com — FortiGate Cheat Sheet","url":"https://defencedev.com/network-tutorials/fortigate/fortigate-useful-cli-commands/","desc":"Ultimate FortiGate Command Cheat Sheet."}]};
